def right_angle_triangle(a, b, c):
    sides = sorted((a, b, c))
    return (
        sides[0] > 0
        and sides[0] + sides[1] > sides[2]
        and sides[0] ** 2 + sides[1] ** 2 == sides[2] ** 2
    )

def find_max(words):
    max_unique = max(len(set(word)) for word in words)
    return min(word for word in words if len(set(word)) == max_unique)

def find_max(words):
    """Return the word with the most unique characters, breaking ties lexicographically."""
    if not words:
        return ""

    best = words[0]
    for word in words[1:]:
        if len(set(word)) > len(set(best)) or (
            len(set(word)) == len(set(best)) and word < best
        ):
            best = word
    return best

